  void Help(){using(var dialog=new WF.Form{Text="使用帮助／无设备测试",Size=new Size(720,600),StartPosition=WF.FormStartPosition.CenterParent,Font=Font,FormBorderStyle=WF.FormBorderStyle.FixedDialog,MaximizeBox=false}){
   var panel=new WF.FlowLayoutPanel{Dock=WF.DockStyle.Fill,FlowDirection=WF.FlowDirection.TopDown,Padding=new WF.Padding(18),WrapContents=false};dialog.Controls.Add(panel);panel.Controls.Add(new WF.Label{Text="文字提问：下方输入问题→发送；拍照后也可连续追问。换题点“新对话／清空”。\n\n直接拍题：自动打开实时预览→拍照等待对焦→连续框选→预览确认；跨页题点“继续拍下一页”。\n\n相机被占用时先关闭其他预览程序。拍照与题图使用原始像素和无损PNG；预览缩放不影响原图。\n\n演示模式使用合成题图、真实模型接口，不代表高拍仪硬件已验证。重启回到正常模式。",AutoSize=true,MaximumSize=new Size(650,0),Font=new Font("Microsoft YaHei",17)});
   panel.Controls.Add(B(Entry.DemoCamera?"退出演示模式":"开启无摄像头演示",()=>{Clear(false);Entry.DemoCamera=!Entry.DemoCamera;hint.Text=Entry.DemoCamera?"演示模式：合成练习题，非真实高拍仪；演示结果会保存到验收文件夹。":"可拍题，也可在下方直接输入问题；拍题后可继续追问。Ctrl+Enter发送。";dialog.Close();_=RefreshDevices();}));
   panel.Controls.Add(B("打开取图测试纸",()=>{var paper=new WF.Form{Text="软件测试题纸（非真实视频展台）",Width=1150,Height=780,StartPosition=WF.FormStartPosition.CenterScreen};var box=new WF.PictureBox{Dock=WF.DockStyle.Fill,SizeMode=WF.PictureBoxSizeMode.Zoom,Image=Raster.ToBitmap(Checks.Chart())};paper.Controls.Add(box);paper.FormClosed+=(_,__)=>box.Image?.Dispose();paper.Show();dialog.Close();}));dialog.ShowDialog(this);
  }}
  void Configure(){Stop("");using(var dialog=new WF.Form{Text="老师设置 · 深度求索",Size=new Size(670,600),StartPosition=WF.FormStartPosition.CenterParent,Font=Font,FormBorderStyle=WF.FormBorderStyle.FixedDialog,MaximizeBox=false}){
   var fields=new WF.TableLayoutPanel{Dock=WF.DockStyle.Fill,ColumnCount=1,Padding=new WF.Padding(18),AutoScroll=true};dialog.Controls.Add(fields);
   var provider=new WF.ComboBox{DropDownStyle=WF.ComboBoxStyle.DropDownList,Dock=WF.DockStyle.Top};provider.Items.AddRange(new object[]{"DeepSeek","Doubao"});provider.SelectedItem=settings.Provider;
   WF.TextBox deep=new WF.TextBox{UseSystemPasswordChar=true,Dock=WF.DockStyle.Top},ark=new WF.TextBox{UseSystemPasswordChar=true,Dock=WF.DockStyle.Top},voice=new WF.TextBox{UseSystemPasswordChar=true,Dock=WF.DockStyle.Top};var limit=new WF.NumericUpDown{Minimum=1,Maximum=1000,Value=settings.DailyLimit,Dock=WF.DockStyle.Top};
   void Field(string label,WF.Control control){fields.Controls.Add(new WF.Label{Text=label,AutoSize=true});fields.Controls.Add(control);}
   Field("文字／看图主模型",provider);Field("DeepSeek Key（留空保留已有值）",deep);Field("豆包 Key（留空保留已有值）",ark);Field("豆包语音 Key（留空保留已有值）",voice);Field("本机每日解题上限",limit);
   fields.Controls.Add(new WF.Label{Text="已有密钥不显示。配置保存在本机当前Windows账户的加密文件内。",AutoSize=true,MaximumSize=new Size(600,0)});
   fields.Controls.Add(B("保存设置",()=>{settings.Provider=(string)provider.SelectedItem;if(deep.Text.Trim().Length>0)settings.DeepSeekApiKey=deep.Text.Trim();if(ark.Text.Trim().Length>0)settings.DoubaoApiKey=ark.Text.Trim();if(voice.Text.Trim().Length>0)settings.VoiceApiKey=voice.Text.Trim();settings.DailyLimit=(int)limit.Value;settings.Save();dialog.Close();status.Text="设置已保存，学生无需登录即可拍题。";}));dialog.ShowDialog(this);
  }}
 }
}
